  // Reconstruction tab
  reconTitle:     { ru: "Восстановление изображения", uz: "Tasvirni tiklash",     en: "Image reconstruction"    },
  reconSubtitle:  { ru: "Когда опорный луч освещает готовую голограмму, происходит дифракция на записанной решётке. Возникают три выходных луча.", uz: "Tayanch nuri tayyor gologrammani yoritganda, yozilgan panjarada difraksiya sodir bo'ladi. Uchta chiqish nuri paydo bo'ladi.", en: "When the reference beam illuminates the finished hologram, diffraction occurs at the recorded grating. Three output beams emerge." },
  order0:         { ru: "0-й порядок: прямой луч (не несёт информации)", uz: "0-chi tartib: to'g'ri nur (ma'lumot olib bermaydi)", en: "0th order: direct beam (carries no information)" },
  order1p:        { ru: "+1-й порядок: ВОССТАНОВЛЕННАЯ объектная волна → 3D изображение!", uz: "+1-chi tartib: TIKLANGAN ob'ekt to'lqini → 3D tasvir!", en: "+1st order: RECONSTRUCTED object wave → 3D image!" },
  order1m:        { ru: "-1-й порядок: сопряжённая волна (псевдоскопическое изображение)", uz: "-1-chi tartib: bog'liq to'lqin (psevdoskopik tasvir)", en: "-1st order: conjugate wave (pseudoscopic image)" },
  reconHighlight: { ru: "Это точная копия оригинальной объектной волны. Глаз воспринимает её как настоящий трёхмерный объект — с параллаксом и глубиной!", uz: "Bu original ob'ekt to'lqinining aniq nusxasi. Ko'z uni haqiqiy uch o'lchamli ob'ekt sifatida — parallaks va chuqurlik bilan — idrok etadi!", en: "This is an exact replica of the original object wave. The eye perceives it as a real three-dimensional object — with parallax and depth!" },
  reconMathTitle: { ru: "Математика восстановления", uz: "Tiklash matematikasi",   en: "Reconstruction mathematics" },
  reconRestoredLabel: { ru: "← ВОССТАНОВЛЕННАЯ ВОЛНА! (1-й порядок) ✓", uz: "← TIKLANGAN TO'LQIN! (1-chi tartib) ✓", en: "← RECONSTRUCTED WAVE! (1st order) ✓" },
  reconDirectLabel:   { ru: "← прямой луч (0-й порядок)",  uz: "← to'g'ri nur (0-chi tartib)",  en: "← direct beam (0th order)"  },
  reconBgLabel:       { ru: "← фон (0-й порядок)",         uz: "← fon (0-chi tartib)",          en: "← background (0th order)"   },
  reconConjLabel:     { ru: "← сопряжённая волна (-1-й порядок)", uz: "← bog'liq to'lqin (-1-chi tartib)", en: "← conjugate wave (-1st order)" },
  reconHighlightTitle:{ ru: "β·Aᵣ·A₀·exp(iφ) — третье слагаемое", uz: "β·Aᵣ·A₀·exp(iφ) — uchinchi had", en: "β·Aᵣ·A₀·exp(iφ) — third term" },
  reconHighlightDesc: { ru: "Это точная копия оригинальной объектной волны A₀·exp(iφ), умноженная на постоянную β·Aᵣ. Глаз воспринимает эту волну как настоящий трёхмерный объект — с параллаксом, глубиной и объёмом. Именно это и является восстановленным голографическим изображением.", uz: "Bu original ob'ekt to'lqinining A₀·exp(iφ) aniq nusxasi, β·Aᵣ doimiysiga ko'paytirilgan. Ko'z bu to'lqinni haqiqiy uch o'lchamli ob'ekt sifatida — parallaks, chuqurlik va hajm bilan — idrok etadi. Aynan shu tiklangan golografik tasvirdir.", en: "This is an exact replica of the original object wave A₀·exp(iφ), multiplied by the constant β·Aᵣ. The eye perceives this wave as a real three-dimensional object — with parallax, depth, and volume. This is the reconstructed holographic image." },
  order0desc:  { ru: "Прямой луч и фон. Не несёт информации об объекте.",    uz: "To'g'ri nur va fon. Ob'ekt haqida ma'lumot olib bermaydi.",      en: "Direct beam and background. Carries no object information."    },
  order1pDesc: { ru: "Восстановленная волна — виртуальное 3D изображение объекта.", uz: "Tiklangan to'lqin — ob'ektning virtual 3D tasviri.",          en: "Reconstructed wave — virtual 3D image of the object."          },
  order1mDesc: { ru: "Сопряжённая волна — реальное перевёрнутое изображение.", uz: "Bog'liq to'lqin — haqiqiy teskari tasvir.",                       en: "Conjugate wave — real inverted image."                         },

